import numpy as np, scipy.sparse.linalg as sla, random, time
from reference import Task

def solve_fast(problem):
    A=problem['matrix']; k=problem['k']; N=A.shape[0]
    v0=np.ones(N, dtype=A.dtype)
    for ncv in (11, 13, 15):
        try:
            vals, vecs=sla.eigs(A,k=k,v0=v0,tol=0, maxiter=N*60, ncv=ncv)
            break
        except Exception as e:
            # print('fail', ncv, e)
            continue
    else:
        vals, vecs=sla.eigs(A,k=k,v0=v0,tol=0, maxiter=N*200, ncv=20)
    pairs=list(zip(vals, vecs.T)); pairs.sort(key=lambda p:-abs(p[0])); return [v for _,v in pairs]

total_bad=0
for seed in range(100):
    pb=Task().generate_problem(300, seed)
    try:
        res=solve_fast(pb)
    except Exception as e:
        print('error compute',seed, e)
        total_bad+=1
        continue
    if not Task().is_solution(pb, res):
        print('invalid',seed)
        total_bad+=1
print('bad',total_bad)
